style.css:
/* Rainbow outline button with shine and shadow */
button, input[type="button"], input[type="submit"] {
    position: relative;
    background: #1a1a1a; /* dark base for contrast */
    color: #fff;
    font-weight: bold;
    padding: 12px 24px;
    border: none;
    border-radius: 12px;
    cursor: pointer;
    overflow: hidden;

    /* Shadow for depth */
    -webkit-box-shadow: 0 5px 15px rgba(0,0,0,0.3);
    -moz-box-shadow: 0 5px 15px rgba(0,0,0,0.3);
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
}

/* Rainbow gradient border effect */
button::before, input[type="button"]::before, input[type="submit"]::before {
    content: '';
    position: absolute;
    top: -2px;
    left: -2px;
    right: -2px;
    bottom: -2px;
    border-radius: 14px;
    padding: 2px;
    background: linear-gradient(45deg, red, orange, yellow, green, blue, indigo, violet, red);
    z-index: -1;
    filter: blur(5px); /* smooth fade */
}

/* Shine effect */
button::after, input[type="button"]::after, input[type="submit"]::after {
    content: '';
    position: absolute;
    top: 0;
    left: -75%;
    width: 50%;
    height: 100%;
    background: rgba(255,255,255,0.3);
    transform: skewX(-25deg);
    transition: all 0.7s;
}

button:hover::after, input[type="button"]:hover::after, input[type="submit"]:hover::after {
    left: 125%;
}

/* Make sure content is on top */
button, input[type="button"], input[type="submit"] {
    position: relative;
    z-index: 1;
}
